head.b:skin:
:root{--bg:#04101c;--panel:#0a1b2c;--panel2:#12293f;--line:rgba(122,180,255,.16);--cyan:#38bdf8;--mint:#5ee6a0;--indigo:#6c8cff;--amber:#ffb44d;--coral:#ff6b6b;--lavender:#ffd400;--text:#f7fcff;--text2:#c3dcf0;--muted:#91b2cc;--on-accent:#04121f;--card-r:16px;--btn-r:12px;--input-r:12px;--chip-r:999px;--card-border:1px;--card-shadow:0 8px 22px rgba(0,0,0,.32);--label-transform:uppercase;--btn-fill:var(--btn-fill);--grid-cols:repeat(5,minmax(0,1fr));--face-blur:18px}
*{box-sizing:border-box}html,body{margin:0;padding:0;background:var(--bg);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}
body{min-height:100vh;background:radial-gradient(900px 500px at 12% -10%,rgba(56,232,255,.13),transparent 60%),radial-gradient(800px 520px at 88% 0,rgba(37,99,235,.16),transparent 55%),radial-gradient(700px 600px at 50% 110%,rgba(62,240,176,.08),transparent 60%),var(--bg);background-attachment:fixed}
a{color:var(--cyan)}.svp-wrap{max-width:1080px;margin:0 auto;padding:28px 18px 40px;position:relative;z-index:2}
.svp-top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px;flex-wrap:wrap}
.svp-brand{display:flex;align-items:center;gap:12px}
.svp-logo{width:44px;height:44px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:20px;color:var(--on-accent);background:var(--btn-fill);box-shadow:0 10px 30px rgba(56,232,255,.25)}
.svp-brand h1{font-size:20px;line-height:1.2;margin:0;letter-spacing:.2px}
.svp-brand p{margin:2px 0 0;font-size:11px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase}
.svp-top-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.svp-face{display:inline-flex}
.svp-face-select{appearance:none;background:var(--panel2);border:var(--card-border) solid var(--line);border-radius:var(--chip-r);color:var(--text);padding:8px 12px;font-size:12px;font-family:inherit;cursor:pointer;max-width:190px}
.svp-face-select:focus{outline:none;border-color:var(--cyan);box-shadow:0 0 0 3px rgba(56,189,248,.15)}
.svp-card{background:var(--panel);border:var(--card-border) solid var(--line);border-radius:var(--card-r);padding:20px;backdrop-filter:blur(18px);box-shadow:0 24px 60px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.04)}
.svp-lock{max-width:520px;margin:8vh auto 0;text-align:left;border-color:rgba(56,232,255,.26)}
.svp-lock h2{margin:0 0 6px;font-size:22px}
.svp-muted{color:var(--muted);font-size:13px;line-height:1.55;margin:0 0 14px}
.svp-label{display:block;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin:14px 0 6px}
.svp-passrow{display:flex;gap:8px}
.svp-passrow input{flex:1}
input,textarea,select{width:100%;background:rgba(6,10,18,.7);border:1px solid var(--line);border-radius:12px;color:var(--text);padding:11px 13px;font-size:14px;outline:none;font-family:inherit}
input:focus,textarea:focus{border-color:rgba(56,232,255,.55);box-shadow:0 0 0 3px rgba(56,232,255,.12)}
textarea{min-height:88px;resize:vertical}
.svp-btn{border:1px solid var(--line);border-radius:12px;padding:10px 15px;font-size:13px;font-weight:600;cursor:pointer;background:rgba(255,255,255,.04);color:var(--text);font-family:inherit;transition:transform .12s ease,background .2s ease,border-color .2s ease}
.svp-btn:hover{transform:translateY(-1px);border-color:rgba(56,232,255,.4)}
.svp-btn:disabled{opacity:.55;cursor:not-allowed;transform:none}
.svp-btn.primary{background:var(--btn-fill);color:var(--on-accent);border:0;box-shadow:0 10px 26px rgba(56,232,255,.22)}
.svp-btn.ghost{background:rgba(255,255,255,.03)}
.svp-btn.icon{padding:10px 12px;min-width:52px}
.svp-btn.danger{border-color:rgba(255,65,54,.35);color:var(--coral)}
.svp-btn.wide{width:100%;margin-top:14px;padding:12px}
.svp-err{color:var(--coral);font-size:13px;margin:12px 0 0;line-height:1.5}
.svp-split{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
.svp-split .svp-btn{flex:1}
.svp-stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:16px}
.svp-stat{background:var(--panel2);border:1px solid var(--line);border-radius:14px;padding:12px 10px;text-align:center}
.svp-stat b{display:block;font-size:20px;letter-spacing:.4px}
.svp-stat span{display:block;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-top:3px}
.svp-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px}
.svp-tabs{display:flex;gap:6px;flex-wrap:wrap;flex:1}
.svp-tab{border:1px solid var(--line);background:rgba(255,255,255,.025);color:var(--muted);border-radius:999px;padding:7px 13px;font-size:12px;cursor:pointer;font-family:inherit}
.svp-tab.active{color:var(--on-accent);background:var(--btn-fill);border-color:transparent;font-weight:700}
.svp-tab b{opacity:.75;font-weight:600;margin-left:4px}
.svp-search{max-width:260px;flex:1 1 180px}
.svp-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px}
.svp-item{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:16px;display:flex;flex-direction:column;gap:10px;backdrop-filter:blur(14px)}
.svp-item-head{display:flex;gap:10px;align-items:flex-start}
.svp-avatar{width:38px;height:38px;flex:0 0 38px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:15px;color:var(--on-accent);background:linear-gradient(135deg,var(--cyan),var(--indigo))}
.svp-item-title{font-size:15px;font-weight:700;line-height:1.25;word-break:break-word;margin:0}
.svp-item-sub{font-size:12px;color:var(--muted);margin:2px 0 0;word-break:break-word}
.svp-tags{display:flex;gap:6px;flex-wrap:wrap}
.svp-tag{font-size:9px;letter-spacing:.12em;text-transform:uppercase;padding:3px 8px;border-radius:999px;border:1px solid rgba(37,99,235,.40);color:var(--indigo);background:rgba(37,99,235,.10)}
.svp-tag.fav{color:var(--amber);border-color:rgba(255,200,92,.4);background:rgba(255,200,92,.09)}
.svp-secret{display:flex;align-items:center;gap:6px;background:rgba(6,10,18,.65);border:1px solid var(--line);border-radius:11px;padding:8px 10px}
.svp-secret code{flex:1;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12.5px;word-break:break-all;color:var(--text)}
.svp-secret .svp-btn{padding:5px 9px;font-size:10px;min-width:0}
.svp-note{font-size:12px;color:var(--muted);white-space:pre-wrap;word-break:break-word;max-height:110px;overflow:auto;line-height:1.5}
.svp-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:auto;padding-top:4px}
.svp-actions .svp-btn{padding:6px 10px;font-size:11px}
.svp-totp{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:22px;letter-spacing:.22em;color:var(--mint);font-weight:700}
.svp-empty{grid-column:1/-1;text-align:center;padding:44px 18px;color:var(--muted);border:1px dashed var(--line);border-radius:18px;font-size:13px}
.svp-savebar{margin-top:18px;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;background:var(--panel2);border:1px solid var(--line);border-radius:16px;padding:14px 16px}
.svp-savebar .svp-btn{white-space:nowrap}
.svp-dirty{color:var(--amber)!important}
.svp-foot{text-align:center;color:var(--muted);font-size:10px;letter-spacing:.14em;text-transform:uppercase;margin-top:34px;opacity:.7}
.svp-modal{position:fixed;inset:0;background:rgba(2,4,9,.78);backdrop-filter:blur(6px);z-index:50;display:flex;align-items:center;justify-content:center;padding:16px}
.svp-modal-card{max-width:520px;width:100%;max-height:92vh;overflow:auto}
.svp-modal h2{margin:0 0 12px;font-size:19px}
.svp-field{margin-bottom:10px}
.svp-field label{display:block;font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:5px}
.svp-modal-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:16px}
.svp-drive-list{display:flex;flex-direction:column;gap:8px;margin-top:12px;max-height:300px;overflow:auto}
.svp-drive-row{display:flex;gap:10px;align-items:center;border:1px solid var(--line);background:rgba(6,10,18,.55);border-radius:12px;padding:10px 12px}
.svp-drive-row div{flex:1;min-width:0}
.svp-drive-row b{display:block;font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.svp-drive-row span{display:block;font-size:10px;color:var(--muted);margin-top:2px}
.svp-row{display:flex;align-items:center;justify-content:space-between;gap:10px}
.svp-row h2{margin:0;font-size:18px}
.svp-pairqr{display:flex;gap:16px;align-items:center;justify-content:center;flex-wrap:wrap;margin-top:12px}
.svp-qr-frame{padding:10px;border-radius:14px;background:#fff;border:1px solid var(--line);line-height:0;width:min(260px,64vw);box-shadow:0 8px 26px rgba(0,0,0,.35)}
.svp-qr-frame svg{display:block;width:100%;height:auto}
.svp-qr-side{flex:1;min-width:170px;max-width:280px}
.svp-qr-code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:22px;letter-spacing:.3em;color:var(--text);text-align:center;margin:0 0 6px}
.svp-pairqr .svp-muted{font-size:11px;line-height:1.5;margin:0}
.svp-chip{display:inline-flex;align-items:center;gap:6px;font-size:11px;letter-spacing:.06em;padding:7px 11px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.04);color:var(--muted);font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:nowrap}
.svp-chip.on{color:var(--mint);border-color:rgba(62,240,176,.35);background:rgba(62,240,176,.10)}
.svp-chip.warn{color:var(--amber);border-color:rgba(255,200,92,.35);background:rgba(255,200,92,.10)}
.svp-livebox{border:1px solid rgba(56,232,255,.24);background:rgba(56,232,255,.05);border-radius:16px;padding:14px;margin-bottom:6px}
.svp-livebox b{font-size:13px}
.svp-gis{display:flex;justify-content:center;margin:10px 0 0;min-height:0}
.svp-gis:empty{margin:0}
.svp-div{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);border-top:1px solid var(--line);margin:16px 0 0;padding-top:12px}
.svp-offline{margin-top:12px;border-top:1px solid var(--line);padding-top:10px}
.svp-offline summary{cursor:pointer;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);list-style:none}
.svp-offline summary::-webkit-details-marker{display:none}
.svp-offline summary::before{content:'+ ';color:var(--cyan)}
.svp-offline[open] summary::before{content:'- '}
.svp-offline[open] summary{margin-bottom:10px}
.svp-livebar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;background:var(--panel2);border:1px solid var(--line);border-radius:16px;padding:11px 14px;margin-bottom:14px;font-size:12px;color:var(--muted)}
.svp-livebar .svp-btn{padding:6px 10px;font-size:11px}
.svp-dot{width:9px;height:9px;border-radius:50%;background:var(--muted);flex:0 0 9px;box-shadow:0 0 0 3px rgba(139,155,180,.14)}
.svp-dot.on{background:var(--mint);box-shadow:0 0 10px rgba(62,240,176,.75)}
.svp-dot.off{background:var(--coral);box-shadow:0 0 10px rgba(255,65,54,.55)}
.svp-lat{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--text);font-weight:700;padding:3px 9px;border-radius:9px;background:rgba(56,232,255,.10);border:1px solid rgba(56,232,255,.28);font-size:11.5px}
.svp-lat.warn{color:var(--amber);background:rgba(255,200,92,.10);border-color:rgba(255,200,92,.3)}
.svp-lat.bad{color:var(--coral);background:rgba(255,65,54,.10);border-color:rgba(255,65,54,.3)}
.svp-log{width:100%;max-height:130px;overflow:auto;font-size:10.5px;line-height:1.55;background:rgba(6,10,18,.6);border:1px solid var(--line);border-radius:12px;padding:8px 10px;white-space:pre-wrap;word-break:break-word;margin:0;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--muted)}
.svp-stamp{font-size:10px;color:var(--muted);letter-spacing:.08em;margin-top:auto;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.svp-viewer-body{margin-top:10px}
.svp-viewer-body img{display:block;max-width:100%;height:auto;border-radius:12px;margin:0 auto}
.svp-viewer-body iframe{display:block;width:100%;height:62vh;border:1px solid var(--line);border-radius:12px;background:#0a0f18}
.svp-viewer-body pre{max-height:60vh;overflow:auto;font-size:11.5px;line-height:1.5;white-space:pre-wrap;word-break:break-word;background:rgba(6,10,18,.6);border:1px solid var(--line);border-radius:12px;padding:10px}
.svp-viewer-body .svp-empty{padding:22px}
[hidden]{display:none!important}
@media(max-width:820px){.svp-stats{grid-template-columns:repeat(3,minmax(0,1fr))}.svp-search{max-width:none;width:100%}}
@media(max-width:520px){.svp-wrap{padding:18px 12px 30px}.svp-lock{margin-top:3vh}.svp-list{grid-template-columns:1fr}.svp-brand h1{font-size:17px}.svp-top{gap:10px}.svp-toolbar{align-items:stretch}.svp-savebar{align-items:stretch}.svp-savebar>div{display:flex;gap:8px;flex-wrap:wrap}}

body.script:
//
(function () {
  'use strict';
  var ITERATIONS = 600000;
  var DEFAULT_CLIENT_ID = '908900914248-pse5k128rl0hoqb07oebhsnngt1i80uj.apps.googleusercontent.com';
  var TABS = [['entries', 'Logins'], ['cards', 'Cards'], ['totps', '2FA'], ['notes', 'Notes'], ['contacts', 'Contacts'], ['files', 'Files'], ['cryptoWallets', 'Crypto']];
  /* SVP-1 realtime backend. generate.js rewrites this line from google-services.json
     (project id, web client id, the project's public web API key and the derived
     database URL). No credential of any kind is baked into the generator: an API key
     and an OAuth client id are public client identifiers that authorise nothing on
     their own - every database read still needs a signed-in session whose uid equals
     the node path. An unbuilt theme can run live mode by typing the API key into
     Google setup, which keeps it in localStorage only. */
  var FB_VERSION = '10.12.2';
  var FB_CFG = { apiKey: '', authDomain: 'vault-35423.firebaseapp.com', projectId: 'vault-35423', databaseURL: 'https://vault-35423-default-rtdb.asia-southeast1.firebasedatabase.app', webClientId: '908900914248-pse5k128rl0hoqb07oebhsnngt1i80uj.apps.googleusercontent.com' };
  /* The 15 faces of the app, bridged from Palette.kt by generate.js at build time. An empty list is
     only ever a template placeholder: a shipped theme always carries all 15, so the page and the
     phone cannot drift into two different lineups. */
  var SVP_THEMES = [];
  var SVP_DEFAULT_FACE = 'aqua';

  /* ===================== THE FACE LAYER (same 15 themes as the app) =====================
   * Every rule in the skin reads a CSS variable, so dressing the page is one pass of
   * setProperty over the bridged tokens - no second stylesheet and no second opinion about what
   * "Solstice" looks like. The phone owns the choice: `meta/face` carries the id the app is
   * wearing, and this page follows it. With nothing signed in there is no phone to follow, so the
   * picker at the top of the page decides and remembers.
   */
  var FACE_TOKENS = {
    bg: '--bg', panel: '--panel', panel2: '--panel2', accent: '--cyan', gold: '--amber',
    link: '--indigo', good: '--mint', bad: '--coral', soft: '--lavender', text: '--text',
    text2: '--text2', muted: '--muted'
  };
  var FACE_STORAGE = 'svp.face';

  function faceById(id) {
    for (var i = 0; i < SVP_THEMES.length; i++) if (SVP_THEMES[i].id === id) return SVP_THEMES[i];
    return null;
  }

  function faceList() { return SVP_THEMES.slice(); }

  /** Contrast for text that sits on a filled accent button, tab or avatar. */
  function inkOn(hexOrRgba) {
    var m = /#([0-9a-f]{6})/i.exec(hexOrRgba || '');
    if (!m) return '#04121f';
    var n = parseInt(m[1], 16);
    var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    return (0.299 * r + 0.587 * g + 0.114 * b) > 150 ? '#10141c' : '#f7fbff';
  }

  function applyFace(id, remember) {
    var theme = faceById(id) || faceById(SVP_DEFAULT_FACE) || faceList()[0];
    if (!theme) return '';
    var style = document.documentElement.style;
    var tokens = theme.tokens || {};
    for (var key in FACE_TOKENS) if (tokens[key]) style.setProperty(FACE_TOKENS[key], tokens[key]);
    var flags = theme.flags || {};
    style.setProperty('--line', flags.hardOutline ? (tokens.text || '#000') : 'rgba(128,128,128,.30)');
    style.setProperty('--on-accent', inkOn(tokens.accent));
    style.setProperty('--card-r', pxOr(flags.cardCorner, 16));
    style.setProperty('--btn-r', pxOr(flags.buttonCorner, 12));
    style.setProperty('--input-r', pxOr(flags.inputCorner, 12));
    style.setProperty('--chip-r', pxOr(flags.chipCorner, 999));
    style.setProperty('--card-border', flags.hardOutline ? '2px' : '1px');
    style.setProperty('--card-shadow', flags.glow ? '0 18px 46px rgba(0,0,0,.32)' : '0 8px 22px rgba(0,0,0,.10)');
    style.setProperty('--label-transform', flags.uppercaseLabels ? 'uppercase' : 'none');
    style.setProperty('--btn-fill', flags.gradientButtons
      ? 'linear-gradient(135deg,' + (tokens.accent || '#2563eb') + ',' + (tokens.good || '#00b84c') + ')'
      : (tokens.accent || '#2563eb'));
    style.setProperty('--grid-cols', layoutColumns(flags.layout));
    style.setProperty('--face-blur', flags.sheen ? '18px' : '0px');
    document.documentElement.setAttribute('data-svp-face', theme.id);
    try { if (remember) localStorage.setItem(FACE_STORAGE, theme.id); } catch (e) { /* private mode */ }
    return theme.id;
  }

  function pxOr(value, fallback) { return (typeof value === 'number' && isFinite(value)) ? value + 'px' : fallback + 'px'; }

  var FACE_COLUMNS = {
    CLASSIC: 'repeat(4,minmax(0,1fr))', BENTO: 'repeat(4,minmax(0,1fr))', STRIP: 'repeat(4,minmax(0,1fr))',
    AGENTIC: 'repeat(2,minmax(0,1fr))', ADAPTIVE: 'repeat(2,minmax(0,1fr))', DUO: 'repeat(2,minmax(0,1fr))',
    LEDGER: 'repeat(2,minmax(0,1fr))', SPLIT: 'repeat(2,minmax(0,1fr))', TRIAD: 'repeat(2,minmax(0,1fr))',
    GENERATIVE: 'repeat(3,minmax(0,1fr))', MOSAIC: 'repeat(3,minmax(0,1fr))', COLUMN: 'repeat(3,minmax(0,1fr))',
    GALLERY: 'repeat(3,minmax(0,1fr))', COMPACT: 'repeat(5,minmax(0,1fr))', DENSE: 'repeat(6,minmax(0,1fr))'
  };
  function layoutColumns(layout) {
    return FACE_COLUMNS[layout] || 'repeat(auto-fill,minmax(150px,1fr))';
  }

  function storedFace() {
    try { return localStorage.getItem(FACE_STORAGE) || ''; } catch (e) { return ''; }
  }

  /** The picker in the header: the app's 15 names, in the app's order. */
  function renderFacePicker() {
    var host = document.getElementById('svp-face');
    if (!host) return;
    var themes = faceList();
    if (!themes.length) { host.textContent = 'No themes are bridged into this file.'; return; }
    var current = document.documentElement.getAttribute('data-svp-face') || '';
    while (host.firstChild) host.removeChild(host.firstChild);
    var select = document.createElement('select');
    select.id = 'svp-face-select';
    select.className = 'svp-face-select';
    select.setAttribute('aria-label', 'Theme face');
    themes.forEach(function (theme) {
      var option = document.createElement('option');
      option.value = theme.id;
      option.textContent = theme.name || theme.id;
      if (theme.id === current) option.selected = true;
      select.appendChild(option);
    });
    select.addEventListener('change', function () { applyFace(select.value, true); repaintFace(); });
    host.appendChild(select);
  }

  /** Re-render whatever reads colours: the list, the counts and the composition ring. */
  function repaintFace() {
    if (typeof scheduleRender === 'function') scheduleRender();
    if (typeof drawComposition === 'function') drawComposition();
  }

  /** Follow the phone: the app writes the id it is wearing, and this side puts it on. */
  function mirrorPhoneFace(raw) {
    var id = typeof raw === 'string' ? raw : (raw && raw.face) || '';
    if (!id || !faceById(id)) return false;
    applyFace(id, true);
    renderFacePicker();
    repaintFace();
    return true;
  }

  /* One listener on one plain string. `meta/face` is not vault data, so it is read the moment a
     live session exists and never blocks or retries: if the phone has not written one yet, the
     browser keeps the face its owner last chose here. */
  function watchPhoneFace() {
    if (!RT.ns || !RT.uid) return;
    try {
      var ref = rtRef('meta/face');
      if (!ref || typeof ref.on !== 'function') return;
      if (RT.faceOff) { try { RT.faceOff(); } catch (e) { /* already detached */ } }
      RT.faceOff = ref.on('value', function (snap) {
        mirrorPhoneFace(snap && typeof snap.val === 'function' ? snap.val() : '');
      });
